/**
 * Tests for ModelCacheLoader — .rvf extraction + offline loading
 */

import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import * as fs from 'fs';
import * as path from 'path';
import * as os from 'os';
import * as crypto from 'crypto';

describe('ModelCacheLoader', () => {
  let tempDir: string;

  beforeEach(() => {
    tempDir = fs.mkdtempSync(path.join(os.tmpdir(), 'agentdb-model-test-'));
  });

  afterEach(() => {
    fs.rmSync(tempDir, { recursive: true, force: true });
  });

  /**
   * Helper: Create a small test .rvf file with dummy model assets.
   */
  async function createTestRvf(outputPath: string, files: Record<string, string>): Promise<void> {
    const sqlJsModule = await import('sql.js');
    const SQL = await sqlJsModule.default();
    const db = new SQL.Database();

    db.run(`
      CREATE TABLE model_assets (
        filename TEXT PRIMARY KEY,
        content  BLOB NOT NULL,
        size     INTEGER NOT NULL,
        sha256   TEXT NOT NULL
      )
    `);
    db.run(`
      CREATE TABLE model_meta (
        key   TEXT PRIMARY KEY,
        value TEXT NOT NULL
      )
    `);
    db.run("INSERT INTO model_meta (key, value) VALUES ('model_id', 'Xenova/test-model')");
    db.run("INSERT INTO model_meta (key, value) VALUES ('dimension', '384')");
    db.run("INSERT INTO model_meta (key, value) VALUES ('format_version', '1')");

    for (const [filename, content] of Object.entries(files)) {
      const buf = Buffer.from(content, 'utf-8');
      const sha256 = crypto.createHash('sha256').update(buf).digest('hex');
      db.run(
        'INSERT INTO model_assets (filename, content, size, sha256) VALUES (?, ?, ?, ?)',
        [filename, buf, buf.length, sha256]
      );
    }

    const data = db.export();
    db.close();
    fs.writeFileSync(outputPath, Buffer.from(data));
  }

  it('should extract files from .rvf and verify checksums', async () => {
    const { ModelCacheLoader } = await import('../../src/model/ModelCacheLoader.js');

    const rvfPath = path.join(tempDir, 'test-model.rvf');
    const dummyFiles = {
      'config.json': '{"model_type":"bert","hidden_size":384}',
      'tokenizer.json': '{"version":"1.0","model":{"type":"BPE"}}',
      'onnx/model_quantized.onnx': 'fake-onnx-binary-data-for-testing',
    };

    await createTestRvf(rvfPath, dummyFiles);

    // Extract from .rvf
    const basePath = await ModelCacheLoader.extractFromRvf(rvfPath, 'test-model');

    // Verify all files were extracted
    const modelDir = path.join(basePath, 'Xenova', 'test-model');
    for (const [filename, expectedContent] of Object.entries(dummyFiles)) {
      const filePath = path.join(modelDir, filename);
      expect(fs.existsSync(filePath)).toBe(true);

      const actualContent = fs.readFileSync(filePath, 'utf-8');
      expect(actualContent).toBe(expectedContent);

      // Verify checksum
      const hash = crypto.createHash('sha256').update(Buffer.from(actualContent)).digest('hex');
      const expectedHash = crypto.createHash('sha256').update(Buffer.from(expectedContent)).digest('hex');
      expect(hash).toBe(expectedHash);
    }
  });

  it('should skip re-extraction when files already exist with correct checksums', async () => {
    const { ModelCacheLoader } = await import('../../src/model/ModelCacheLoader.js');

    const rvfPath = path.join(tempDir, 'test-model.rvf');
    const dummyFiles = {
      'config.json': '{"test":"data"}',
    };

    await createTestRvf(rvfPath, dummyFiles);

    // Extract once
    const basePath1 = await ModelCacheLoader.extractFromRvf(rvfPath, 'test-model');
    const filePath = path.join(basePath1, 'Xenova', 'test-model', 'config.json');
    const mtime1 = fs.statSync(filePath).mtimeMs;

    // Wait briefly to ensure mtime would differ on re-write
    await new Promise(r => setTimeout(r, 50));

    // Extract again — should skip (checksums match)
    await ModelCacheLoader.extractFromRvf(rvfPath, 'test-model');
    const mtime2 = fs.statSync(filePath).mtimeMs;

    expect(mtime2).toBe(mtime1);
  });

  it('should set offline mode in EmbeddingService when model is cached', async () => {
    // Mock ModelCacheLoader.resolve to return a cached result
    const mockResult = { localPath: '/tmp/mock-models', fromBundle: true };

    vi.doMock('../../src/model/ModelCacheLoader.js', () => ({
      ModelCacheLoader: {
        resolve: vi.fn().mockResolvedValue(mockResult),
      },
    }));

    // Simulate what EmbeddingService.initialize() does
    const envSettings: Record<string, unknown> = {};
    const mockTransformersEnv = new Proxy(envSettings, {
      set(target, prop, value) {
        target[prop as string] = value;
        return true;
      },
    });

    // Replicate the EmbeddingService logic for the bundled model path
    const { ModelCacheLoader } = await import('../../src/model/ModelCacheLoader.js');
    const cached = await ModelCacheLoader.resolve('all-MiniLM-L6-v2');

    if (cached) {
      mockTransformersEnv.localModelPath = cached.localPath;
      mockTransformersEnv.allowRemoteModels = false;
      mockTransformersEnv.cacheDir = cached.localPath;
    }

    expect(envSettings.localModelPath).toBe('/tmp/mock-models');
    expect(envSettings.allowRemoteModels).toBe(false);
    expect(envSettings.cacheDir).toBe('/tmp/mock-models');

    vi.doUnmock('../../src/model/ModelCacheLoader.js');
  });
});

# RuVector Graph Database - Primary Database for AgentDB v2

## 🎯 Architecture Change

AgentDB v2 now uses **RuVector GraphDatabase** as the PRIMARY database, with SQLite as a legacy fallback.

### Before (v1.x)

```
Primary: SQLite (sql.js) → SQL queries
Vector: RuVector → Embeddings only
```

### After (v2.0.0)

```
Primary: RuVector GraphDatabase → Cypher queries + vectors + hypergraphs
Legacy: SQLite (sql.js) → Backward compatibility only
```

## 🚀 Why Graph Database?

### 1. **Native Vector Integration**

- Episodes stored as nodes WITH their embeddings
- No separate vector table needed
- Semantic search built into graph queries

### 2. **Cypher Queries** (Neo4j-compatible)

```cypher
// Find successful episodes from last 30 days
MATCH (e:Episode)
WHERE e.success = 'true'
  AND e.createdAt > timestamp() - 2592000
RETURN e ORDER BY e.reward DESC LIMIT 10

// Find skills that led to high rewards
MATCH (e:Episode)-[USED_SKILL]->(s:Skill)
WHERE e.reward > 0.8
RETURN s, AVG(e.reward) as avgReward
ORDER BY avgReward DESC
```

### 3. **Hyperedges** (Multi-Node Relationships)

```typescript
// Connect 3+ episodes that collaborated on a task
await db.createHyperedge({
  nodes: ["ep-1", "ep-2", "ep-3"],
  description: "COLLABORATED_ON_PROJECT",
  embedding: projectEmbedding,
  confidence: 0.85,
  metadata: { project: "AI Research" },
});
```

### 4. **ACID Persistence**

- Full transactional support
- begin/commit/rollback
- Automatic persistence to disk
- No manual save() calls needed

### 5. **Performance**

| Operation       | RuVector Graph  | SQLite       |
| --------------- | --------------- | ------------ |
| Node Creation   | 9.17K ops/sec   | ~1K ops/sec  |
| Batch Insert    | 131.10K ops/sec | ~10K ops/sec |
| Vector Search   | 2.35K ops/sec   | N/A          |
| k-hop Traversal | 10.28K ops/sec  | Slow JOINs   |

## 📦 New Dependencies

```json
{
  "dependencies": {
    "ruvector": "^0.1.24", // Vector DB
    "@ruvector/graph-node": "^0.1.15", // Graph DB (PRIMARY)
    "@ruvector/router": "^0.1.15", // Semantic routing
    "sql.js": "^1.13.0" // Legacy fallback
  }
}
```

## 🔄 Automatic Mode Detection

The system automatically detects which database to use:

```typescript
import { createUnifiedDatabase } from "agentdb";

// AUTO-DETECT: Checks file extension and content
const db = await createUnifiedDatabase("./mydb.graph", embedder);

// FORCE GRAPH MODE (recommended for new projects)
const db = await createUnifiedDatabase("./mydb.graph", embedder, {
  forceMode: "graph",
});

// FORCE LEGACY MODE (for old databases)
const db = await createUnifiedDatabase("./old.db", embedder, {
  forceMode: "sqlite-legacy",
});

// AUTO-MIGRATE from SQLite to Graph
const db = await createUnifiedDatabase("./old.db", embedder, {
  autoMigrate: true, // Converts SQLite → Graph automatically
});
```

### Detection Logic

1. **File Extension**
   - `.graph` → Always use GraphDatabase
   - `.db` → Check if it's SQLite

2. **File Content**
   - Reads first 16 bytes
   - Checks for "SQLite format 3" signature
   - If SQLite → Legacy mode (unless autoMigrate=true)
   - If not SQLite → Graph mode

3. **New Database**
   - No existing file → Use GraphDatabase (recommended)

## 🗄️ Data Model Mapping

### Episodes → Graph Nodes

**SQLite (Old)**:

```sql
CREATE TABLE episodes (
  id INTEGER PRIMARY KEY,
  session_id TEXT,
  task TEXT,
  reward REAL,
  success BOOLEAN
);

-- Separate embeddings table
CREATE TABLE embeddings (
  episode_id INTEGER,
  embedding BLOB
);
```

**RuVector Graph (New)**:

```typescript
// Single unified node with embedded vector
await graphDb.storeEpisode(
  {
    id: "ep-123",
    sessionId: "session-1",
    task: "Implement feature",
    reward: 0.95,
    success: true,
    input: "User requirements...",
    output: "Code implementation...",
    critique: "Could improve error handling",
  },
  embedding,
); // Vector stored WITH the node
```

### Skills → Graph Nodes

**SQLite (Old)**:

```sql
CREATE TABLE skills (
  id INTEGER PRIMARY KEY,
  name TEXT UNIQUE,
  code TEXT,
  usage_count INTEGER
);
```

**RuVector Graph (New)**:

```typescript
await graphDb.storeSkill(
  {
    id: "skill-123",
    name: "error-handling",
    description: "Advanced error handling pattern",
    code: "try { ... } catch (e) { ... }",
    usageCount: 45,
    avgReward: 0.88,
  },
  codeEmbedding,
);
```

### Causal Relationships → Graph Edges

**SQLite (Old)**:

```sql
CREATE TABLE causal_edges (
  id INTEGER PRIMARY KEY,
  from_memory_id INTEGER,
  to_memory_id INTEGER,
  mechanism TEXT,
  uplift REAL,
  FOREIGN KEY (from_memory_id) REFERENCES episodes(id),
  FOREIGN KEY (to_memory_id) REFERENCES episodes(id)
);
```

**RuVector Graph (New)**:

```typescript
await graphDb.createCausalEdge(
  {
    from: "ep-1",
    to: "ep-2",
    mechanism: "Better error handling led to higher success rate",
    uplift: 0.25,
    confidence: 0.92,
    sampleSize: 100,
  },
  mechanismEmbedding,
);
```

## 🔄 Migration Tool

